"use strict";(self.webpackChunksedelpeuch_net=self.webpackChunksedelpeuch_net||[]).push([["35429"],{99e3(e){e.exports=JSON.parse('{"tag":{"label":"python","permalink":"/docs/tags/python","allTagsPath":"/docs/tags","count":15,"items":[{"id":"projects/professionnel/outils-internes","title":"Automatisation du quotidien : outils internes","description":"Kiosque d\'\xe9tat du cluster, recherche de composants, suivi de campagne, site de documentation, suivi de l\'activit\xe9 GitHub et bots : des outils d\xe9velopp\xe9s pour supprimer les t\xe2ches r\xe9p\xe9titives d\'une \xe9quipe du CATIE, tous d\xe9ploy\xe9s de la m\xeame fa\xe7on sur Kubernetes.","permalink":"/docs/projects/professionnel/outils-internes"},{"id":"projects/personnel/body_analysis","title":"Body Analysis","description":"Application de suivi et d\'analyse corporelle (FastAPI, React, PostgreSQL, stockage S3) : phases \xe0 r\xe8gles dynamiques, s\xe9ances de course, de natation et de musculation (montre et Hevy), mensurations, photos recal\xe9es automatiquement, synchronisation par une appli Android et serveur MCP.","permalink":"/docs/projects/personnel/body_analysis"},{"id":"projects/associatif/cameleon","title":"Cam\xe9l\xe9on","description":"Tableau de bord Flask et OpenCV pour enregistrer le flux d\'une cam\xe9ra IP et le diffuser dans l\'open space du fablab EirLab, lanc\xe9 depuis une simple cl\xe9 USB.","permalink":"/docs/projects/associatif/cameleon"},{"id":"projects/professionnel/cicd","title":"CI/CD - Workflows GitHub Actions mutualis\xe9s","description":"Biblioth\xe8que de workflows GitHub Actions r\xe9utilisables (g\xe9n\xe9rique, Python, ROS, Mbed, Zephyr) appel\xe9e par plusieurs dizaines de d\xe9p\xf4ts du CATIE, du test au d\xe9ploiement Helm ou Compose, avec une documentation v\xe9rifi\xe9e automatiquement contre le code.","permalink":"/docs/projects/professionnel/cicd"},{"id":"projects/personnel/colis-tracker","title":"Colis Tracker","description":"Suivi de colis Colissimo et Chronopost auto-h\xe9berg\xe9, sans cl\xe9 API ni service tiers : interrogation de l\'endpoint de suivi public de La Poste, import automatique des num\xe9ros depuis les mails d\'exp\xe9dition (IMAP), date de livraison pr\xe9vue, notifications ntfy, serveur MCP.","permalink":"/docs/projects/personnel/colis-tracker"},{"id":"projects/professionnel/vision-embarquee","title":"D\xe9ploiement de mod\xe8les de vision sur NVIDIA Jetson","description":"Mise en production de mod\xe8les de vision par ordinateur sur NVIDIA Jetson AGX Orin et Orin Nano pour des clients industriels du CATIE, du mod\xe8le entra\xeen\xe9 au service livr\xe9 sur la carte.","permalink":"/docs/projects/professionnel/vision-embarquee"},{"id":"projects/associatif/haricot-apringalle","title":"Haricot","description":"Bo\xeetier Raspberry Pi qui photographie la croissance d\'une plante \xe0 intervalle r\xe9gulier et g\xe9n\xe8re des timelapses depuis un tableau de bord web, projet d\'Antoine Pringalle \xe0 EirLab.","permalink":"/docs/projects/associatif/haricot-apringalle"},{"id":"projects/professionnel/inspection","title":"Inspection visuelle automatis\xe9e de v\xe9hicules","description":"Pipeline de vision par ordinateur embarqu\xe9 pour la d\xe9tection automatique de dommages sur v\xe9hicules neufs en parcs portuaires, jusqu\'\xe0 20 000 images en 3 secondes par v\xe9hicule. Traitement parall\xe9lis\xe9 des images brutes et inf\xe9rence embarqu\xe9e sur site.","permalink":"/docs/projects/professionnel/inspection"},{"id":"projects/associatif/reachy-mobile","title":"Reachy Mobile","description":"Rendre mobile le robot humano\xefde Reachy en l\'installant sur une base motoris\xe9e EZ Wheel : pilotage par interface web, d\xe9tection des visiteurs et partie de morpion, projet men\xe9 au fablab EirLab.","permalink":"/docs/projects/associatif/reachy-mobile"},{"id":"projects/personnel/recallarr","title":"Recallarr","description":"Journal personnel de ce qui a \xe9t\xe9 regard\xe9 dans Jellyfin, qui survit au nettoyage de la m\xe9diath\xe8que : synchronisation par webhook et r\xe9conciliation quotidienne, r\xe8gles de note et de favori, suivi des nouvelles saisons et des suites, serveur MCP, interface HTMX.","permalink":"/docs/projects/personnel/recallarr"},{"id":"projects/associatif/ronoco","title":"Ronoco","description":"Interface no-code pour programmer des robots ROS (manipulateurs MoveIt et robots roulants move_base) sans \xe9crire de code ; premier prototype d\xe9velopp\xe9 en stage de 2e ann\xe9e d\'\xe9cole d\'ing\xe9nieur.","permalink":"/docs/projects/associatif/ronoco"},{"id":"projects/personnel/task-horizon","title":"TaskHorizon","description":"Application Kanban FastAPI + React d\xe9ploy\xe9e sur AWS EKS via Terraform, avec un chart Helm multi-environnement et un pipeline CI/CD GitHub Actions du commit au cluster.","permalink":"/docs/projects/personnel/task-horizon"},{"id":"projects/associatif/vertical-plotter","title":"Vertical Plotter","description":"Traceur vertical qui dessine sur les tableaux blancs d\'EirLab, pilot\xe9 par Arduino, avec une cha\xeene de conversion SVG vers trajectoires adapt\xe9e aux 2 Ko de m\xe9moire du microcontr\xf4leur.","permalink":"/docs/projects/associatif/vertical-plotter"},{"id":"projects/associatif/wolf","title":"Wolf","description":"Application Flask de gestion interne d\'EirLab Community reliant les adh\xe9rents \xe0 Dolibarr : identification par carte, attribution des formations, gestion du stock par code-barres.","permalink":"/docs/projects/associatif/wolf"},{"id":"projects/personnel/ytdl-sub-ui","title":"ytdl-sub-ui","description":"Interface web qui pilote ytdl-sub, le t\xe9l\xe9chargeur de cha\xeenes YouTube vers Jellyfin : recherche et ajout de cha\xeenes sans compte, r\xe9tention, r\xe9glages et suivi des passages, serveur MCP, chaque \xe9criture valid\xe9e par ytdl-sub avant d\'\xeatre mise en place.","permalink":"/docs/projects/personnel/ytdl-sub-ui"}],"unlisted":false}}')}}]);